// Title: Aspose.Cells C# – Export PDF with 300 DPI Image Resampling and Maximum JPEG Quality
// Description: Shows how to call PdfSaveOptions.SetImageResample(300, 100) in C# so that every image in the generated PDF is resampled to 300 DPI and saved with 100 % JPEG quality.
// Keywords: Aspose.Cells | PdfSaveOptions | SetImageResample | 300 DPI | high‑resolution PDF | JPEG quality 100 | .NET | C# | image resampling | PDF export
// Common Searches: Aspose.Cells set PDF image DPI C# | PdfSaveOptions SetImageResample example | increase image resolution in PDF generated by Aspose.Cells | C# export workbook to PDF with 300 DPI images | maximum JPEG quality Aspose.Cells PDF
// Developer Intent: Configure PDF export to resample images at 300 DPI with full JPEG quality.
// Use Cases: Print‑ready financial reports that require crisp charts and logos. | Marketing brochures where embedded photos must stay sharp after conversion. | Technical documentation with high‑resolution diagrams for professional printing.
// AI Prompts: Provide C# code that uses Aspose.Cells PdfSaveOptions to resample all PDF images to 300 DPI and set JPEG quality to 100. | Explain the impact of the two parameters in SetImageResample on PDF file size and visual clarity. | Show a complete example that loads an existing workbook, applies 300 DPI image resampling, and saves the result as a PDF.

using System;
using Aspose.Cells;

// Shows how to call PdfSaveOptions.SetImageResample(300, 100) in C# so that every image in the generated PDF is resampled to 300 DPI and saved with 100 % JPEG quality.
class Program
{
    static void Main()
    {
        // Create a new workbook (or load an existing one)
        Workbook workbook = new Workbook();

        // Add sample data to demonstrate the PDF content
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Sample data for PDF with high‑resolution images");
        sheet.Cells["A2"].PutValue("This PDF will have images resampled at 300 DPI.");

        // Configure PDF save options to resample images at 300 DPI with maximum JPEG quality
        PdfSaveOptions pdfSaveOptions = new PdfSaveOptions();
        // desiredPPI = 300 (high quality), jpegQuality = 100 (best quality)
        pdfSaveOptions.SetImageResample(300, 100);

        // Save the workbook as a PDF using the configured options
        workbook.Save("output_300dpi.pdf", pdfSaveOptions);
    }
}
